export type ThemePref = "auto" | "light" | "dark";

const THEME_PREFS: ThemePref[] = ["auto", "light", "dark"];

/**
 * Base path for logo image files.
 * Override via configureLogo() when the app stores logos elsewhere.
 */
let logoBasePath = "icons/";

/** Set the base path for BlockBrain logo SVGs. Default: "icons/". */
export function configureLogo(basePath: string): void {
  logoBasePath = basePath;
}

/**
 * Apply a theme preference to the document.
 * Sets `document.documentElement.dataset.theme` and swaps `img.logo` src.
 */
export function applyTheme(pref: ThemePref): void {
  const dark =
    pref === "dark" ||
    (pref === "auto" && matchMedia("(prefers-color-scheme: dark)").matches);
  document.documentElement.dataset["theme"] = dark ? "dark" : "light";
  document.querySelectorAll("img.logo").forEach((img) => {
    (img as HTMLImageElement).src = `${logoBasePath}blockbrain_logo_${dark ? "dark" : "light"}.svg`;
  });
}

/** Cycle to the next theme preference. Returns the new preference. */
export function cycleTheme(current: ThemePref): ThemePref {
  const idx = THEME_PREFS.indexOf(current);
  return THEME_PREFS[(idx + 1) % THEME_PREFS.length];
}

/** Return the SVG icon markup for the given theme preference (Heroicons outline). */
export function themeIcon(pref: ThemePref): string {
  if (pref === "light") {
    return `<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" width="16" height="16">
      <path stroke-linecap="round" stroke-linejoin="round" d="M12 3v2.25m6.364.386-1.591 1.591M21 12h-2.25m-.386 6.364-1.591-1.591M12 18.75V21m-4.773-4.227-1.591 1.591M5.25 12H3m4.227-4.773L5.636 5.636M15.75 12a3.75 3.75 0 1 1-7.5 0 3.75 3.75 0 0 1 7.5 0Z" />
    </svg>`;
  }
  if (pref === "dark") {
    return `<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" width="16" height="16">
      <path stroke-linecap="round" stroke-linejoin="round" d="M21.752 15.002A9.72 9.72 0 0 1 18 15.75c-5.385 0-9.75-4.365-9.75-9.75 0-1.33.266-2.597.748-3.752A9.753 9.753 0 0 0 3 11.25C3 16.635 7.365 21 12.75 21a9.753 9.753 0 0 0 9.002-5.998Z" />
    </svg>`;
  }
  // Auto: monitor icon
  return `<svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="1.5" stroke="currentColor" width="16" height="16">
    <path stroke-linecap="round" stroke-linejoin="round" d="M9 17.25v1.007a3 3 0 0 1-.879 2.122L7.5 21h9l-.621-.621A3 3 0 0 1 15 18.257V17.25m6-12V15a2.25 2.25 0 0 1-2.25 2.25H5.25A2.25 2.25 0 0 1 3 15V5.25m18 0A2.25 2.25 0 0 0 18.75 3H5.25A2.25 2.25 0 0 0 3 5.25m18 0H3" />
  </svg>`;
}
